mapper.select:

WHERE IS_DELETE = 0
 AND YEAR = #{year}
 AND MONTH = #{month}
 AND FACTORY_CODE = #{factoryCode}
 AND PRODUCT_CODE = #{productCode}
 AND PRODUCT_DESC = #{productDesc}
 AND LOCATION_TYPE = #{locationType}
 AND SALE_QTY = #{saleQty}
 AND ORDER_QTY = #{orderQty}

mapper.insert:
insert into T_MP_HISTORY_SALE_QTY
(ID, YEAR, MONTH, FACTORY_CODE, PRODUCT_CODE, PRODUCT_DESC, LOCATION_TYPE, SALE_QTY, ORDER_QTY, REMARK, IS_DELETE, CREATE_BY, CREATE_TIME, UPDATE_BY, UPDATE_TIME
)
select NULL id, x.*
from (

    select
    #{historySaleQty.year,jdbcType= INTEGER} year,
    #{historySaleQty.month,jdbcType= INTEGER} month, #{historySaleQty.factoryCode,jdbcType=VARCHAR} factory_code,
    #{historySaleQty.productCode,jdbcType= VARCHAR} product_code, #{historySaleQty.productDesc,jdbcType= VARCHAR} product_desc,
